         w.mainView.image.getSamples( I ); parts.starless.mainView.image.getSamples( S ); parts.stars.mainView.image.getSamples( T );
         var worst = 0;
         for ( var i = 0; i < n; ++i ) worst = Math.max( worst, Math.abs( 1 - ( 1 - S[i] )*( 1 - T[i] ) - I[i] ) );
