      check( "a YouTube preset set to crossfade loops by crossfading", [ yt.crossfade, yt.pingPong ], [ true, false ] );
      check( "a social one set to back and forth loops back and forth", [ pp.pingPong, pp.crossfade ], [ true, false ] );
