         for ( var y = m; y < h - m; ++y ) for ( var x = m; x < w - m; ++x ) { worst = Math.max( worst, Math.abs( box[y*w + x] - nat[y*w + x] ) ); peak = Math.max( peak, box[y*w + x] ); }
