         FlyThrough.renderFinal( fx.scene, [ spec ], Object.assign( {}, o, { growth: 0.3 } ), dir, { cancelAfter: 1 } );
         var other = FlyThrough.renderFinal( fx.scene, [ spec ], Object.assign( {}, o, { growth: 0.3 } ), dir, {} );
