         for ( i = 0; i < n; ++i ) { dOut = Math.max( dOut, Math.abs( js.out[i] - nat.out[i] ) ); if ( hdr ) dX = Math.max( dX, Math.abs( js.excess[i] - nat.excess[i] ) ); }
