         var xy = Solve.invertSimilarity( f, p[0], p[1] );
         if ( xy[0] >= 0 && xy[1] >= 0 && xy[0] < W && xy[1] < H ) dets.push( { x: xy[0], y: xy[1], flux: Math.pow( 10, -0.4*t.G ) } );
