         function rnd() { s = ( Math.imul( s, 1664525 ) + 1013904223 ) >>> 0; return s/4294967296; }
         var f = { a: scale*Math.cos( turn ), b: scale*Math.sin( turn ), parity: parity, tx: 0, ty: 0 };
         var c0 = Solve.applySimilarity( f, W/2, H/2 ); f.tx = -c0[0]; f.ty = -c0[1];
