            dets.push( { x: xy[0] + 0.3*( rnd() - 0.5 ), y: xy[1] + 0.3*( rnd() - 0.5 ), flux: Math.pow( 10, -0.4*t.G )*( 0.8 + 0.4*rnd() ) } );
